import {BASE_URL, BASE_URL_EACCOUNT} from './httpClient';

export const createAccountServices = (fetchRequest: any) => ({
  async clearBackground(imageBase64: string) {
    try {
      const endpoint =
        '/services/envelope/api/p/envelope/multimediaProcessing/image/focusBackground/autoFocus';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'text/plain',
        },
        body: imageBase64,
        typeOfResponse: 'text',
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.log('err clearBackground', error);
      return Promise.reject(error);
    }
  },

  async listImageSignature(body: any) {
    try {
      const endpoint = '/services/uaa/api/account/signature-eaccount-search';
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.log('err listImageSignature', error);
      return Promise.reject(error);
    }
  },
});
