import {View, Text, TouchableOpacity} from 'react-native';
import React from 'react';
import {TabType} from '../..';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import TextCM from '../../../../../../../components/Text';

type Props = {
  tabType: TabType;
  setTabType: (type: TabType) => void;
};

const ListTabType = ({tabType, setTabType}: Props) => {
  const {t} = useTranslation();

  const LIST = [
    {
      label: t('NT.TxtFromAccount'),
      type: TabType.Account,
    },
    {
      label: t('NT.TxtFromFile'),
      type: TabType.File,
    },
    {
      label: t('NT.TxtHandDrawn'),
      type: TabType.Art,
    },
  ];

  const renderItem = ({label, type}: {label: string; type: TabType}) => {
    return (
      <TouchableOpacity
        key={type}
        style={[styles.btnItem, type === tabType && styles.btnItemActive]}
        onPress={() => setTabType(type)}>
        <TextCM
          style={[styles.txtItem, type === tabType && styles.txtItemActive]}>
          {label}
        </TextCM>
      </TouchableOpacity>
    );
  };

  return <View style={styles.ctn}>{LIST.map(renderItem)}</View>;
};

export default ListTabType;
