import {BASE_URL} from './httpClient';

export const createGeneralSettingServices = (fetchRequest: any) => ({
  async getListDigitalCertificate(userId: number) {
    try {
      const endpoint = '/services/uaa/api/user-agreement-details/by-user';
      const response = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        params: {userId},
      });
      return Promise.resolve(response.data);
    } catch (error) {
      console.log('err getGeneralSetting', error);
      return Promise.reject(error);
    }
  },
});
